        check2("run_fail_key_u64", sql`${t2.failKey} IS NULL OR ${t2.failKey} ~ '^(0|[1-9][0-9]{0,19})$'`),
        check2("run_entry_secrets_count", nullOrFlatList(t2.entrySecretIds, ENTRY_SECRET_MAX_COUNT))
