        memo: text2("memo"),
        /** The verified transfer into the vault (base58 signature): one signature, one payment. */
        txSignature: text2("tx_signature").unique("entry_fee_payment_tx_signature_unique"),
        /** Its slot (u64 decimal). */
        slot: text2("slot"),
        /** How the request that made it authenticated (ENTRY_FEE_VIAS), with its API key and agent wallet when one. */
        via: text2("via").$type().notNull(),
        apiKeyId: text2("api_key_id"),
        agentWalletId: uuid3("agent_wallet_id"),
        /** A quote's lapse (its blockhash's lifetime); null once none applies. */
        expiresAt: tz2("expires_at"),
        paidAt: tz2("paid_at"),
