          sql`CASE WHEN NOT (${isU64(t2.fundBaseUnits)}) THEN false WHEN NOT (${isU64(t2.amountBaseUnits)}) THEN true ELSE ${t2.fundBaseUnits}::numeric <= ${t2.amountBaseUnits}::numeric END`
