          sql`CASE WHEN NOT (${isU64(t2.creatorBaseUnits)}) THEN false WHEN NOT (${isU64(t2.fundBaseUnits)}) OR NOT (${isU64(t2.amountBaseUnits)}) THEN true ELSE ${t2.fundBaseUnits}::numeric + ${t2.creatorBaseUnits}::numeric <= ${t2.amountBaseUnits}::numeric END`
