        /** The wallet (base58) that paid the allowance: the refund goes back to it. */
        wallet: text2("wallet").notNull(),
        amountCents: bigint4("amount_cents", { mode: "bigint" }).notNull(),
        /** The transaction (base58 signature) carrying the deposit: known once built, required from held on. */
        depositTx: text2("deposit_tx"),
