        likeCount: integer2("like_count").notNull().default(0),
        trustedLikeCount: integer2("trusted_like_count").notNull().default(0),
        /** On a root, its replies (root_id this comment) that are not deleted; 0 on a reply. */
        replyCount: integer2("reply_count").notNull().default(0),
        /** Its reports (comment_report rows). */
        reportCount: integer2("report_count").notNull().default(0),
        /** Why it was held, one sentence its author and admins are shown, and when; kept after an admin publishes or hides it. */
        heldReason: text2("held_reason"),
        heldAt: tz2("held_at"),
        /** The admin who last moderated it, and when; null until one did (null again once that account is deleted). Reports never auto-hide a comment an admin restored. */
        moderatedBy: text2("moderated_by").references(() => user.id, { onDelete: "set null" }),
