        /** Betting during the bounty phase: the window [the toggle-on time or opens_at, the deadline). */
        bountyOn: boolean4("bounty_on").notNull().default(false),
        /** Betting during the live race: the window [race start, race end). */
        raceOn: boolean4("race_on").notNull().default(false),
