        house: sideMarketHouse("house").notNull().default("excluded"),
        status: sideMarketStatus("status").notNull().default("off"),
        // ---- the Market account (null until opened)
        cluster: solanaCluster("cluster"),
        programId: text2("program_id"),
        /** The Market PDA ["market", competition_id]. */
        address: text2("address"),
        /** The vault token account PDA ["vault", market]. */
        vault: text2("vault"),
        /** The LMSR liquidity b, in base units. */
        b: baseUnits("b"),
        /** Scratches stop at it: the competition's deadline. */
        lockAt: tz2("lock_at"),
        /** Anyone may void the market after it (deadline + 14 days). */
        voidAfter: tz2("void_after"),
        /** The trading windows [from, until) as set on chain; null while unset. */
        bountyFrom: tz2("bounty_from"),
        bountyUntil: tz2("bounty_until"),
        raceFrom: tz2("race_from"),
        raceUntil: tz2("race_until"),
        /** The chain's race slot when it holds the judging window [deadline, lease end) instead of a live race (race_from/race_until then stay null); null while unset. */
        judgingFrom: tz2("judging_from"),
