      {
        competitionId: uuid3("competition_id").primaryKey().references(() => competition.id, { onDelete: "restrict" }),
        ranAt: tz2("ran_at").defaultNow().notNull(),
        poolBaseUnits: text2("pool_base_units").notNull(),
        distributedBaseUnits: text2("distributed_base_units").notNull(),
        dustBaseUnits: text2("dust_base_units").notNull(),
        candidates: integer2("candidates").notNull(),
        recipients: integer2("recipients").notNull(),
        settings: jsonb("settings").$type().notNull(),
        budgetLeftBaseUnits: text2("budget_left_base_units").notNull(),
        /** The tail's pool, part of pool_base_units; null when the round ran no tail. */
        tailPoolBaseUnits: text2("tail_pool_base_units"),
        /** What the tail's rewards sum to, part of distributed_base_units; null when the round ran no tail. */
        tailDistributedBaseUnits: text2("tail_distributed_base_units"),
        /** How many tail rewards (tier 0) it wrote, part of recipients; null when the round ran no tail. */
        tailRecipients: integer2("tail_recipients")
      },
      (t2) => [
        // the desk's last rounds
        index("participation_round_ran_at_idx").on(t2.ranAt),
        check2("participation_round_pool_u64", isU64(t2.poolBaseUnits)),
        check2("participation_round_distributed_u64", isU64(t2.distributedBaseUnits)),
        check2("participation_round_dust_u64", isU64(t2.dustBaseUnits)),
        check2("participation_round_budget_left_u64", isU64(t2.budgetLeftBaseUnits)),
        // CASE, so a value the u64 checks refuse is never cast (theirs is the error, not numeric's)
        check2(
          "participation_round_sums",
          sql`CASE WHEN ${isU64(t2.poolBaseUnits)} AND ${isU64(t2.distributedBaseUnits)} AND ${isU64(t2.dustBaseUnits)} THEN ${t2.distributedBaseUnits}::numeric + ${t2.dustBaseUnits}::numeric = ${t2.poolBaseUnits}::numeric ELSE true END`
        ),
        check2("participation_round_counts", sql`${t2.candidates} >= 0 AND ${t2.recipients} BETWEEN 0 AND ${t2.candidates}`),
        check2("participation_round_settings_object", sql`jsonb_typeof(${t2.settings}) = 'object'`),
        check2("participation_round_tail_pool_u64", nullOr2(t2.tailPoolBaseUnits, isU64(t2.tailPoolBaseUnits))),
        check2("participation_round_tail_distributed_u64", nullOr2(t2.tailDistributedBaseUnits, isU64(t2.tailDistributedBaseUnits))),
        check2(
          "participation_round_tail_set",
          sql`(${t2.tailPoolBaseUnits} IS NULL) = (${t2.tailDistributedBaseUnits} IS NULL) AND (${t2.tailPoolBaseUnits} IS NULL) = (${t2.tailRecipients} IS NULL)`
        ),
        check2("participation_round_tail_counts", nullOr2(t2.tailRecipients, sql`${t2.tailRecipients} BETWEEN 0 AND ${t2.recipients}`)),
        // the tail pays at most its pool, and is part of the totals; CASE, so a value the u64 checks refuse is never cast
        check2(
          "participation_round_tail_sums",
          sql`CASE WHEN ${isU64(t2.tailPoolBaseUnits)} AND ${isU64(t2.tailDistributedBaseUnits)} AND ${isU64(t2.poolBaseUnits)} AND ${isU64(t2.distributedBaseUnits)} THEN ${t2.tailDistributedBaseUnits}::numeric <= ${t2.tailPoolBaseUnits}::numeric AND ${t2.tailPoolBaseUnits}::numeric <= ${t2.poolBaseUnits}::numeric AND ${t2.tailDistributedBaseUnits}::numeric <= ${t2.distributedBaseUnits}::numeric ELSE true END`
        )
      ]
