    andList2 = (names5) => names5.length <= 1 ? names5.join("") : `${names5.slice(0, -1).join(", ")} and ${names5.at(-1)}`;
    orList2 = (names5) => names5.length <= 1 ? names5.join("") : `${names5.slice(0, -1).join(", ")} or ${names5.at(-1)}`;
