      twinHold: 2 * HC_TWIN_ABOVE === CHEAT_CHECK.m + 1 ? `scores at least ${HC_DELTA_J} SOL over the median of its ${CHEAT_CHECK.m} twins` : `scores above at least ${HC_TWIN_ABOVE} of its ${CHEAT_CHECK.m} twins and at least ${HC_DELTA_J} SOL over their median`,
      appealM: CHEAT_CHECK.appeal_m,
      appealHours: CHEAT_CHECK.appeal_hours,
      sigma: CHEAT_CHECK.twin.sigma,
      shift: CHEAT_CHECK.twin.shift_slots,
